import yaml,glob
live={'ajc-albanese','ajc-fbc','ajc-pic0av','ajc-rr','ajcr-cert-r2','ajcr-charts','ajcr-divrep','ajcr-w5-av'}
rows=[]
for f in glob.glob('.archon-horizon/inbox/local/items/*.yaml'):
    d=yaml.safe_load(open(f)) or {}
