    md=d.get('metadata') or {}
    pv=md.get('provenance') or {}
    t=pv.get('task')
    if t and t not in live:
        rows.append((d['id'],d.get('kind'),t,pv.get('run'),d.get('body','').split('\n')[0][:70]))
for r in sorted(rows,key=lambda x:x[0]): print(' | '.join(str(x) for x in r))
print('count',len(rows))
EOF

