import yaml,glob,collections
kinds=collections.Counter(); tot=0
for f in glob.glob('.archon-horizon/inbox/local/items/*.yaml'):
    d=yaml.safe_load(open(f)) or {}
    if d.get('status')=='open':
        kinds[d.get('kind')]+=1; tot+=1
print('inbox open total',tot,'nonprotection',tot-kinds['protection'],dict(kinds))
r=collections.Counter()
for f in glob.glob('.archon-horizon/roadmap/items/*.yaml'):
    d=yaml.safe_load(open(f)) or {}
    r[d.get('status')]+=1
print('roadmap',dict(r))
t=collections.Counter()
for f in glob.glob('.archon-horizon/tasks/items/*.yaml'):
    d=yaml.safe_load(open(f)) or {}
    t[d.get('status')]+=1
print('tasks',dict(t))
EOF

